ClassDeclaration Parser::parseClass() {
    const auto keyword = consume(TokenType::Class, "'class'");
    const auto name = consume(TokenType::Identifier, "class name");
    ClassDeclaration declaration;
    declaration.name = name.text;
    declaration.location = keyword.location;
    if (match(TokenType::Colon)) {
        do {
            AccessLevel access = AccessLevel::Public;
            bool isVirtual = false;
            for (;;) {
                if (match(TokenType::Public)) access = AccessLevel::Public;
                else if (match(TokenType::Protected)) access = AccessLevel::Protected;
                else if (match(TokenType::Private)) access = AccessLevel::Private;
                else if (match(TokenType::Virtual)) {
                    if (isVirtual) error(previous(), "duplicate 'virtual' base modifier");
                    isVirtual = true;
                } else {
                    break;
                }
            }
            const auto base = consume(TokenType::Identifier, "base class name");
            declaration.baseClassNames.push_back(base.text);
            declaration.baseLocations.push_back(base.location);
            declaration.baseAccess.push_back(access);
            declaration.baseVirtual.push_back(isVirtual);
            if (declaration.baseClassNames.size() == 1) {
                declaration.baseClassName = base.text;
                declaration.baseLocation = base.location;
            }
        } while (match(TokenType::Comma));
    }
    consume(TokenType::LeftBrace, "'{' after class name");
    AccessLevel memberAccess = AccessLevel::Public;
    while (!check(TokenType::RightBrace) && !check(TokenType::End)) {
        skipNewlines();
        if (check(TokenType::RightBrace) || check(TokenType::End)) {
            break;
        }
        if ((check(TokenType::Public) || check(TokenType::Protected) ||
             check(TokenType::Private)) &&
            current_ + 1 < tokens_.size() &&
            tokens_[current_ + 1].type == TokenType::Colon) {
            if (match(TokenType::Public)) memberAccess = AccessLevel::Public;
            else if (match(TokenType::Protected)) memberAccess = AccessLevel::Protected;
            else {
                match(TokenType::Private);
                memberAccess = AccessLevel::Private;
            }
            consume(TokenType::Colon, "':' after access section");
            continue;
        }
        if (check(TokenType::Identifier) && current().text == "destroy" &&
            current_ + 1 < tokens_.size() &&
            tokens_[current_ + 1].type == TokenType::LeftParen) {
            const auto destructorName = current();
            ++current_;
            auto destructor = parseMethod(destructorName, destructorName, false);
            destructor.returnType = "void";
            destructor.destructor = true;
            destructor.access = memberAccess;
            declaration.methods.push_back(std::move(destructor));
            continue;
        }
        const auto type = current();
        const auto typeName = parseType(true);
        if (type.type == TokenType::Identifier && typeName == declaration.name &&
            check(TokenType::LeftParen)) {
            auto constructor = parseMethod(type, type, true);
            constructor.access = memberAccess;
            declaration.methods.push_back(std::move(constructor));
            continue;
        }
        const auto member = consume(TokenType::Identifier, "field or method name");
        if (check(TokenType::LeftParen)) {
            if (member.text == "destroy" && typeName != "void") {
                error(member, "destructor must be declared void");
            }
            auto method = parseMethod(type, member, false);
            if (member.text == "destroy") {
                method.destructor = true;
                method.returnType = "void";
            }
            method.access = memberAccess;
            declaration.methods.push_back(std::move(method));
        } else {
            if (typeName == "void") error(type, "fields cannot have type void");
            consumeStatementTerminator();
            declaration.fields.push_back({typeName, member.text, type.location, memberAccess});
        }
    }
    consume(TokenType::RightBrace, "'}' after class body");
    return declaration;
}

std::string Parser::parseType(bool allowVoid) {
    if (match(TokenType::Int)) return "int";
    if (match(TokenType::StringType)) return "string";
    if (allowVoid && match(TokenType::Void)) return "void";
    if (check(TokenType::Identifier)) return tokens_[current_++].text;
    error(current(), "expected type name");
}

std::vector<Parameter> Parser::parseParameters() {
    std::vector<Parameter> parameters;
    consume(TokenType::LeftParen, "'(' before parameters");
    if (!check(TokenType::RightParen)) {
        do {
            const auto location = current().location;
            const auto type = parseType();
            const auto name = consume(TokenType::Identifier, "parameter name");
            parameters.push_back({type, name.text, location});
        } while (match(TokenType::Comma));
    }
    consume(TokenType::RightParen, "')' after parameters");
    return parameters;
}

MethodDeclaration Parser::parseMethod(const Token& typeOrName, const Token& methodName,
                                      bool constructor) {
    MethodDeclaration method;
    method.name = methodName.text;
    method.returnType = constructor ? "void" :
                        (typeOrName.type == TokenType::Int ? "int" :
                         typeOrName.type == TokenType::StringType ? "string" :
                         typeOrName.type == TokenType::Void ? "void" : typeOrName.text);
    method.location = typeOrName.location;
    method.constructor = constructor;
    method.parameters = parseParameters();
    method.body = parseBlock();
    return method;
}

